const d = $input.item.json || {};
const err = d.error || {};
const wf = d.workflow || {};

return {
  json: {
    timestamp: new Date().toISOString(),
    workflowName: wf.name || 'Unknown Workflow',
    workflowId: wf.id || '',
    executionId: d.execution?.id || d.id || '',
    failedNode: err.node?.name || d.lastNodeExecuted || '',
    errorMessage: err.message || d.message || 'Unknown error',
    errorType: err.name || d.name || '',
    stack: (err.stack || '').toString().substring(0, 5000)
  }
};

const d = $input.item.json || {};
let form = {};
let workDrive = {};
try {
  workDrive = $('Prepare WorkDrive Files').item.json || {};
} catch (e) {
  workDrive = {};
}

const resumeText = (d.text || '').substring(0, 12000);

let candidateName = d['Full Name'] || form['Full Name'] || '';
let email = d['Email Address'] || form['Email Address'] || '';
let phone = d['Phone Number'] || form['Phone Number'] || '';
let position = d['Position Applied For'] || form['Position Applied For'] || '';
let linkedin = d['LinkedIn Profile'] || form['LinkedIn Profile'] || '';
const yearsOfExp = d['Years of Experience'] || form['Years of Experience'] || 0;

if (!email) {
  const emailPatterns = [
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/,
    /email[:\s]*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,})/i,
    /([A-Za-z0-9._%+-]+@gmail\.com)/i,
    /([A-Za-z0-9._%+-]+@yahoo\.com)/i,
    /([A-Za-z0-9._%+-]+@outlook\.com)/i,
  ];
  for (const pattern of emailPatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      email = match[match.length - 1];
      if (email && email.includes('@')) break;
    }
  }
  if (!email) email = '';
}

if (!candidateName) {
  const nameLine = (resumeText.split('\n')[0] || '').trim();
  if (nameLine && nameLine.length > 2 && nameLine.length < 60 && !nameLine.includes('@') && !nameLine.match(/\d+/)) {
    candidateName = nameLine;
  }
  if (!candidateName) {
    const regardsPatterns = [/(?:regards|sincerely|best regards|kind regards|warm regards|yours)[,\s]+([A-Za-z\s]+)/i];
    for (const pattern of regardsPatterns) {
      const match = resumeText.match(pattern);
      if (match) {
        const name = match[match.length - 1].trim();
        if (name.length > 2 && name.length < 60 && !name.includes('@') && !name.match(/^[0-9]+$/)) {
          candidateName = name;
          break;
        }
      }
    }
  }
  if (!candidateName) candidateName = 'Unknown';
}

if (!phone) {
  const phonePatterns = [
    /(?:phone|mobile|ph|tel|contact)[:\s]+([\d\s\-\(\)\+\.]+(?:\d{7,15}))/i,
    /(\+\d{1,3}[\s.-]?\d{1,4}[\s.-]?\d{1,9})/,
    /(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/,
    /(\d{1,3}[\s.-]?\d{3,4}[\s.-]?\d{4,5})/,
  ];
  for (const pattern of phonePatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      phone = match[match.length - 1].trim().replace(/^[^\d\+]/g, '');
      if (phone.match(/\d{7,}/)) break;
    }
  }
}

if (!linkedin) {
  const linkedinPatterns = [/linkedin\.com\/in\/([\w\-]+)/i, /li\.in\/([\w\-]+)/i];
  for (const pattern of linkedinPatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      linkedin = match[0].includes('linkedin.com') ? 'https://' + match[0] : 'https://linkedin.com/in/' + match[1];
      break;
    }
  }
}

if (!position) position = 'Not Specified';

return {
  json: {
    source: workDrive.source || d.source || 'form',
    candidateName,
    email,
    phone: phone || '',
    position,
    yearsOfExp,
    linkedin: linkedin || '',
    resumeText,
    workdriveFileId: workDrive.fileId || d.workdriveFileId || d.resourceId || '',
    workdriveFileName: workDrive.fileName || d.workdriveFileName || d.fileName || '',
    sourceFolderId: workDrive.sourceFolderId || d.sourceFolderId || '',
    processedFolderId: workDrive.processedFolderId || d.processedFolderId || '',
    submittedAt: new Date().toISOString(),
  },
};

const d = $input.item.json;
const fromRaw   = d.from || '';
const senderEmail= (fromRaw.match(/<(.+?)>/) || [])[1] || fromRaw;
const resumeText = (d.text || '').substring(0, 12000);

let extractedEmail = '';
const emailPatterns = [
  /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/,
  /email[:\s]*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,})/i,
  /([A-Za-z0-9._%+-]+@gmail\.com)/i,
  /([A-Za-z0-9._%+-]+@yahoo\.com)/i,
  /([A-Za-z0-9._%+-]+@outlook\.com)/i
];
for (const pattern of emailPatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    extractedEmail = match[match.length - 1];
    if (extractedEmail && extractedEmail.includes('@')) break;
  }
}
const finalEmail = extractedEmail || senderEmail;

let candidateName = fromRaw.replace(/<.*>/, '').trim() || 'Unknown';
const nameLine = (resumeText.split('\n')[0] || '').trim();
if (nameLine && nameLine.length > 2 && nameLine.length < 60 && !nameLine.includes('@') && !nameLine.match(/\d+/)) {
  candidateName = nameLine;
}

let phone = '';
const phonePatterns = [
  /(?:phone|mobile|ph|tel|contact)[:\s]+([\d\s\-\(\)\+\.]+(?:\d{7,15}))/i,
  /(\+\d{1,3}[\s.-]?\d{1,4}[\s.-]?\d{1,9})/,
  /(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/,
  /(\d{1,3}[\s.-]?\d{3,4}[\s.-]?\d{4,5})/
];
for (const pattern of phonePatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    phone = match[match.length - 1].trim().replace(/^[^\d\+]/g, '');
    if (phone.match(/\d{7,}/)) break;
  }
}

let linkedin = '';
const linkedinPatterns = [
  /linkedin\.com\/in\/([\w\-]+)/i,
  /li\.in\/([\w\-]+)/i
];
for (const pattern of linkedinPatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    linkedin = match[0].includes('linkedin.com') ? 'https://' + match[0] : 'https://linkedin.com/in/' + match[1];
    break;
  }
}

let position = 'Open Application';
const subject = (d.subject || '').trim();
if (subject && subject.length > 3) {
  let cleanSubject = subject.replace(/^(re|fwd|fw)[:\s]?/gi, '').trim();
  const fieldPattern = /(?:position|role|designation|apply|applying)[:\s]+([^-\n]+)/i;
  const fieldMatch = cleanSubject.match(fieldPattern);
  if (fieldMatch && fieldMatch[1]) {
    position = fieldMatch[1].trim();
    if (position.length < 2 || position.length > 100) position = 'Open Application';
  }
  if (position === 'Open Application') {
    const keywords = ['frontend developer','backend developer','fullstack developer','full stack developer','devops engineer','qa engineer','software engineer','data scientist','cloud architect','senior developer','junior developer','developer','engineer','analyst','manager','architect','designer'];
    for (const keyword of keywords) {
      if (cleanSubject.toLowerCase().includes(keyword)) {
        position = keyword.charAt(0).toUpperCase() + keyword.slice(1);
        break;
      }
    }
  }
  if (position === 'Open Application') {
    position = cleanSubject.replace(/application|resume|cv|curriculum|vitae/gi, '').trim();
    if (position.length < 2 || position.length > 100) position = 'Open Application';
  }
}

return {
  json: {
    source:        'email',
    candidateName: candidateName,
    email:         finalEmail,
    phone:         phone,
    position:      position,
    yearsOfExp:    0,
    linkedin:      linkedin,
    resumeText:    resumeText,
    submittedAt:   new Date().toISOString()
  }
};

const d = { ...$input.item.json };
delete d.resumeText;
return { json: d };

const d = $input.item.json || {};
const resumeText = (d.resumeText || '').trim();

const validationErrors = [];
if (!resumeText || resumeText.length < 100)
  validationErrors.push('Resume text too short or empty');
if (resumeText.length < 200 && resumeText.split(' ').length < 30)
  validationErrors.push('Possible corrupted PDF');

let resumeHash = '';
try {
  const crypto = require('crypto');
  resumeHash = crypto
    .createHash('sha256')
    .update(resumeText.substring(0, 5000).toLowerCase().replace(/\s+/g, ' '))
    .digest('hex')
    .substring(0, 16);
} catch(e) {
  resumeHash = 'hash_' + Date.now();
}

return {
  json: {
    ...d,
    resumeHash,
    resumeLength: resumeText.length,
    validationErrors: validationErrors.join('; ') || null,
    isValidResume: validationErrors.length === 0,
    processingStartMs: Date.now(),
  }
};

const normMap = {
  'javascript': 'JavaScript', 'java script': 'JavaScript', 'js': 'JavaScript',
  'typescript': 'TypeScript', 'ts': 'TypeScript',
  'react': 'React', 'reactjs': 'React', 'react.js': 'React',
  'angularjs': 'Angular', 'angular.js': 'Angular',
  'vuejs': 'Vue.js', 'vue': 'Vue.js',
  'node': 'Node.js', 'nodejs': 'Node.js', 'node js': 'Node.js',
  'expressjs': 'Express.js', 'express': 'Express.js',
  'nextjs': 'Next.js', 'next': 'Next.js',
  'postgres': 'PostgreSQL', 'postgresql': 'PostgreSQL',
  'mongo': 'MongoDB', 'mongodb': 'MongoDB',
  'python3': 'Python', 'py': 'Python',
  'mysql': 'MySQL', 'my sql': 'MySQL',
  'amazon web services': 'AWS',
  'tailwind': 'Tailwind CSS', 'tailwindcss': 'Tailwind CSS',
  'bootstrap4': 'Bootstrap', 'bootstrap5': 'Bootstrap',
