  'pytorch': 'PyTorch',
  'github actions': 'GitHub Actions',
  'ci/cd': 'CI/CD', 'cicd': 'CI/CD',
};

function normalizeSkillList(skillStr) {
  if (!skillStr || typeof skillStr !== 'string') return skillStr || '';
  return skillStr.split(',')
    .map(s => {
      const trimmed = s.trim();
      const key = trimmed.toLowerCase().replace(/[.\s-]/g, '');
      for (const [pattern, canonical] of Object.entries(normMap)) {
        if (key === pattern.replace(/[.\s-]/g, '')) return canonical;
      }
      return trimmed;
    })
    .filter(Boolean)
    .filter((v, i, arr) => arr.findIndex(x => x.toLowerCase() === v.toLowerCase()) === i)
    .join(', ');
}

const rawInput = $input.item.json || {};
const d = rawInput.output || rawInput || {};

// Restore candidate contact details from Resume Validation & Hash node (index-aligned)
let contact = {};
try {
  contact = $('Resume Validation & Hash').item.json || {};
} catch (e) {
  contact = {};
}

// Convert camelCase to snake_case for Save Candidate postgres node inputs
return {
  json: {
    submitted_at: contact.submittedAt || contact.submitted_at || new Date().toISOString(),
    processed_at: new Date().toISOString(),
    source: contact.source || 'unknown',
    candidate_name: contact.candidateName || contact.candidate_name || 'Unknown',
    email: (contact.email || '').trim() || ('no-email-' + (contact.resumeHash || Date.now()) + '@hireflow.internal'),
    phone: contact.phone || '',
    position: contact.position || '',
    years_of_exp: Number(contact.yearsOfExp || contact.years_of_exp || d.totalExperienceYears || 0),
    linkedin: contact.linkedin || '',

    current_job_title: d.currentJobTitle || '',
    highest_degree: d.highestDegree || '',
    degree: d.degree || '',
    college: d.college || '',
    city: d.city || '',
    passout_year: parseInt(d.passoutYear) || null,
    internship_completed: (String(d.internship || '').toLowerCase().includes('yes') || Boolean(d.internshipCompany)),
    certifications: d.certifications || '',

    frontend_skills: normalizeSkillList(d.frontendSkills),
    frontend_level: d.frontendLevel || '',
    backend_skills: normalizeSkillList(d.backendSkills),
    backend_level: d.backendLevel || '',
    database_skills: normalizeSkillList(d.databaseSkills),
    database_level: d.databaseLevel || '',
    ai_ml_skills: normalizeSkillList(d.aiMlSkills),
    ai_ml_level: d.aiMlLevel || '',
    cloud_devops: normalizeSkillList(d.cloudDevOps),
    programming_langs: normalizeSkillList(d.programmingLanguages),
    notable_projects: d.notableProjects || '',

    resume_text: contact.resumeText || contact.resume_text || '',

    workdrive_file_id: contact.workdriveFileId || contact.workdrive_file_id || null,
    workdrive_file_name: contact.workdriveFileName || contact.workdrive_file_name || null,
    source_folder_id: contact.sourceFolderId || contact.source_folder_id || null,
    processed_folder_id: contact.processedFolderId || contact.processed_folder_id || null
  }
};

const d = $input.item.json;
let projects = [];
try {
  projects = typeof d.projectDetails === 'string' ? JSON.parse(d.projectDetails) : (d.projectDetails || []);
} catch(e) { projects = []; }

const complexityWeights = { 'Enterprise': 10, 'Advanced': 7, 'Intermediate': 4, 'Beginner': 2 };
const projectCount = projects.length || Math.min(5, (d.notableProjects || '').split('|').length || 0);
const totalWeight = projects.reduce((sum, p) => sum + (complexityWeights[p.complexity] || 4), 0);
const projectComplexityScore = projectCount > 0
  ? Math.min(10, Math.round((totalWeight / projectCount) * 10) / 10)
  : 0;

return {
  json: {
    ...d,
    project_count: projectCount,
    project_complexity_score: projectComplexityScore,
    projects_parsed: projects
  }
};

const d = $input.item.json;
const resumeText = d.resumeText || '';
let atsScore = 20;
if (/education|academic/i.test(resumeText)) atsScore += 5;
if (/experience|internship|projects/i.test(resumeText)) atsScore += 5;
if (/skills|technologies/i.test(resumeText)) atsScore += 5;
let contactScore = 5;
if (d.email) contactScore += 5;
if (d.phone) contactScore += 5;
const wordCount = resumeText.split(/\s+/).length;
let lengthScore = wordCount >= 300 && wordCount <= 1200 ? 15 : 8;
const formattingScore = (resumeText.match(/•|\*|-/g) || []).length >= 5 ? 15 : 10;
const grammarScore = 10;
const resumeQualityScore = Math.min(100, atsScore + contactScore + lengthScore + formattingScore + grammarScore);
return { json: { ...d, resume_quality_score: resumeQualityScore } };

const d = $input.item.json;
const prompt = `You are an expert, evidence-based technical recruiter evaluating candidates against the Job Description.

EVALUATE 7 DISTINCT CATEGORIES (Each has its own max score):
1. technicalScore (0-30): Matching technical stack skills explicitly evidenced in resume.
2. projectScore (0-25): Depth, count, and complexity of projects.
3. experienceScore (0-15): Internship, freelance, or full-time experience.
4. educationScore (0-10): Degree relevance, college repute, CGPA.
5. resumeQualityScore (0-10): Formatting, clarity, structure.
6. certificationScore (0-5): Relevant industry certifications.
7. achievementScore (0-5): Hackathons, awards, coding profiles.

totalScore = sum of all 7 categories (0-100).

CRITICAL SCORING RULES:
- Never assign identical scores to different candidates unless resumes are identical.
- Every single category score MUST provide explicit evidence text in scoreEvidence.
- A total score above 80 REQUIRES internship experience or 2+ advanced projects.
- A total score of 50-75 is normal for freshers with basic project proof.

=== JOB DESCRIPTION ===
${d.jd_text}

=== CANDIDATE: ${d.candidateName || 'Unknown'} ===
Position: ${d.position || 'Not specified'}
Experience: ${d.totalExperienceYears || d.yearsOfExp || 0} years
Degree: ${d.degree || d.highestDegree || 'Not mentioned'} (${d.specialization || ''})
College: ${d.college || 'Not mentioned'}
CGPA: ${d.cgpa || 'N/A'}
Passout Year: ${d.passoutYear || 'N/A'}
Internship: ${d.internship || 'No'} at ${d.internshipCompany || 'N/A'} (${d.internshipRole || ''})
GitHub: ${d.githubProfile || 'N/A'}
Portfolio: ${d.portfolioWebsite || 'N/A'}

Frontend Skills: ${d.frontendSkills || 'None'}
Backend Skills: ${d.backendSkills || 'None'}
Database Skills: ${d.databaseSkills || 'None'}
AI/ML Skills: ${d.aiMlSkills || 'None'}
Cloud/DevOps: ${d.cloudDevOps || 'None'}
Languages: ${d.programmingLanguages || 'None'}
Certifications: ${d.certifications || 'None'}
Projects: ${d.notableProjects || 'None'}
Project Complexity Score: ${d.project_complexity_score || 0}/10

Resume text (excerpt):
${(d.resumeText || '').substring(0, 3000)}

=== RESPOND ONLY WITH STRICT VALID JSON (NO MARKDOWN, NO BACKTICKS) ===
{
  "technicalScore": <0-30>,
  "projectScore": <0-25>,
  "experienceScore": <0-15>,
  "educationScore": <0-10>,
  "resumeQualityScore": <0-10>,
  "certificationScore": <0-5>,
  "achievementScore": <0-5>,
  "totalScore": <sum of 7 scores, 0-100>,
  "confidenceScore": <0-100>,
  "grade": "<A+|A|B+|B|C|D|F>",
  "recommendation": "<Strong Hire|Hire|Consider|Reject>",
  "insights": {
    "strengths": ["strength 1", "strength 2"],
    "weaknesses": ["weakness 1", "weakness 2"],
    "recommendedRole": "Full Stack Developer",
    "experienceLevel": "Fresher|Junior|Mid|Senior",
    "keyTechnologies": ["React", "Node.js", "PostgreSQL"],
    "hiringNotes": "Key note for recruiter"
  },
  "scoreEvidence": {
    "technical": "Exact proof of technical skills found",
    "projects": "Proof of projects",
    "experience": "Proof of experience",
    "education": "Proof of education",
    "resumeQuality": "Proof of formatting",
    "certifications": "Proof of certifications",
    "achievements": "Proof of achievements"
  },
  "fieldConfidence": {
    "college": 0.95,
    "degree": 0.98,
    "cgpa": 0.90,
    "passoutYear": 0.95,
    "internshipCompany": 0.90
  }
}`;

return { json: { ...d, aiPrompt: prompt } };

const d = $input.item.json;
const fromNode = (name) => {
  try { return $(name).item.json || {}; } catch (e) { return {}; }
};
const triggers = fromNode('Merge Triggers');
const validationNode = fromNode('Resume Validation & Hash');
const extracted = fromNode('Extract — All Skills & Details');
const normalized = fromNode('Normalize Skills');
const complexityNode = fromNode('Project Complexity Analysis');
const qualityNode = fromNode('Resume Quality Analysis');
const jdNode = fromNode('Pre-filled JD');
const promptNode = fromNode('Build Scoring Prompt (/100)');
const m = { ...triggers, ...validationNode, ...extracted, ...normalized, ...complexityNode, ...qualityNode, ...jdNode, ...promptNode, ...d };
const clean = (v) => String(v ?? '').trim();
const first = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '');
const pickStr = (...vals) => {
  const found = vals.map(clean).find(v => v && v.toLowerCase() !== 'n/a' && v.toLowerCase() !== 'none' && v !== 'undefined');
  return found || '';
};

let remote = {};
try {
  const rawRemote = first(d.text, d.text1, d.text2, d.output, d.output1, d.output2, d.response?.text, (d.choices || [])[0]?.message?.content);
  if (rawRemote !== undefined) {
    const cleaned = String(rawRemote).replace(/```json\s*/gi, '').replace(/```\s*/g, '').replace(/^[^{]*/, '').replace(/[^}]*$/, '');
    remote = JSON.parse(cleaned);
  }
} catch (e) { remote = {}; }

const insights = remote.insights || {};
const scoreEvidence = remote.scoreEvidence || {};
const fieldConfidence = remote.fieldConfidence || {};

const technical_score = Number(remote.technicalScore || 0);
const project_score = Number(remote.projectScore || 0);
const experience_score = Number(remote.experienceScore || 0);
const education_score = Number(remote.educationScore || 0);
const resume_quality_score = Number(remote.resumeQualityScore || m.resume_quality_score || 0);
const certification_score = Number(remote.certificationScore || 0);
const achievement_score = Number(remote.achievementScore || 0);

const total_score = Number(remote.totalScore || (technical_score + project_score + experience_score + education_score + resume_quality_score + certification_score + achievement_score));
const grade = remote.grade || (total_score >= 90 ? 'A+' : total_score >= 80 ? 'A' : total_score >= 70 ? 'B+' : total_score >= 60 ? 'B' : total_score >= 50 ? 'C' : total_score >= 40 ? 'D' : 'F');
const recommendation = remote.recommendation || (total_score >= 80 ? 'Strong Hire' : total_score >= 65 ? 'Hire' : total_score >= 50 ? 'Consider' : 'Reject');

const strengths = Array.isArray(insights.strengths) ? insights.strengths.join(' | ') : (remote.strengths || '');
const weaknesses = Array.isArray(insights.weaknesses) ? insights.weaknesses.join(' | ') : (remote.weaknesses || '');

return {
  json: {
    submitted_at: pickStr(m.submittedAt, m.submitted_at) || new Date().toISOString(),
    processed_at: new Date().toISOString(),
    source: pickStr(m.source) || 'unknown',
    candidate_name: pickStr(m.candidateName, m.candidate_name) || 'Unknown',
    email: pickStr(m.email) || ('no-email-' + (m.resumeHash || Date.now()) + '@hireflow.internal'),
    phone: pickStr(m.phone) || '',
    position: pickStr(m.position) || '',
    years_of_exp: Number(m.totalExperienceYears || m.yearsOfExp || 0),
    linkedin: pickStr(m.linkedin) || '',
    github: pickStr(m.githubProfile) || '',
    portfolio: pickStr(m.portfolioWebsite) || '',
    current_job_title: pickStr(m.currentJobTitle) || '',
    highest_degree: pickStr(m.highestDegree, m.degree) || '',
    degree: pickStr(m.degree, m.highestDegree) || '',
    college: pickStr(m.college) || '',
    city: pickStr(m.city) || '',
    passout_year: parseInt(m.passoutYear) || null,
    internship_completed: (pickStr(m.internship).toLowerCase().includes('yes') || Boolean(m.internshipCompany)),
    internship_company: pickStr(m.internshipCompany) || '',
    internship_role: pickStr(m.internshipRole) || '',
    cgpa: parseFloat(m.cgpa) || null,
    specialization: pickStr(m.specialization) || '',
    certifications: pickStr(m.certifications) || '',
    frontend_skills: pickStr(m.frontendSkills) || '',
    frontend_level: pickStr(m.frontendLevel) || '',
    backend_skills: pickStr(m.backendSkills) || '',
    backend_level: pickStr(m.backendLevel) || '',
    database_skills: pickStr(m.databaseSkills) || '',
    database_level: pickStr(m.databaseLevel) || '',
    ai_ml_skills: pickStr(m.aiMlSkills) || '',
    ai_ml_level: pickStr(m.aiMlLevel) || '',
    cloud_devops: pickStr(m.cloudDevOps) || '',
    programming_langs: pickStr(m.programmingLanguages) || '',
    notable_projects: pickStr(m.notableProjects) || '',
    project_count: Number(m.project_count || 0),
    project_complexity_score: Number(m.project_complexity_score || 0),
    certification_count: (pickStr(m.certifications).split(',').filter(Boolean).length),
    resume_quality_score,
    confidence_score: Number(remote.confidenceScore || 85),
    jd_title: pickStr(m.jd_title, m.jdTitle) || '',
    jd_company: pickStr(m.jd_company, m.jdCompany) || '',
    total_score,
    technical_score,
    project_score,
    education_score,
    certification_score,
    achievement_score,
    frontend_score: Math.round(technical_score * 0.4),
    backend_score: Math.round(technical_score * 0.4),
    database_score: Math.round(technical_score * 0.2),
    ai_ml_score: Number(remote.aiMlScore || 0),
    exp_score: experience_score,
    soft_score: Number(remote.softSkillsScore || 3),
    grade,
    recommendation,
    is_qualified: total_score >= 50,
    summary: JSON.stringify(insights),
    strengths,
    weaknesses,
    score_evidence: JSON.stringify(scoreEvidence),
    field_confidence: JSON.stringify(fieldConfidence),
    recommended_role: insights.recommendedRole || 'Full Stack Developer',
    experience_level: insights.experienceLevel || 'Fresher',
    key_technologies: Array.isArray(insights.keyTechnologies) ? insights.keyTechnologies.join(', ') : '',
    hiring_note: insights.hiringNotes || remote.hiringNote || '',
    resume_hash: pickStr(m.resumeHash) || '',
    processing_ms: Date.now() - Number(m.processingStartMs || Date.now())
  }
};

const d = $input.item.json;
const score = d.total_score || 0;
const hasInternship = d.internship_completed === true;
const projectScore = d.project_score || 0;
const resumeQuality = d.resume_quality_score || 0;
const techScore = d.technical_score || 0;
let recommendation = 'Reject';
let rationale = '';
if (score >= 82 && techScore >= 18 && (hasInternship || projectScore >= 18)) {
  recommendation = 'Strong Hire';
  rationale = 'High technical alignment with verified project and internship experience.';
} else if (score >= 68 && techScore >= 12) {
  recommendation = 'Hire';
  rationale = 'Good score with solid technical foundation.';
} else if (score >= 50 && (projectScore >= 10 || resumeQuality >= 60)) {
  recommendation = 'Consider';
  rationale = 'Moderate match showing potential through projects or quality layout.';
} else {
  recommendation = 'Reject';
  rationale = 'Does not meet minimum requirements for this position.';
}
return { json: { ...d, recommendation, recommendation_rationale: rationale } };

