const config = $input.first()?.json || {};
const sourceFolderId = String(config.sourceFolderId || '').trim();
const processedFolderId = String(config.processedFolderId || '').trim();

return $input.all().map(({ json }) => {
  const attrs = json.attributes || {};
  const fileId = json.id || json.resourceId || attrs.id || '';
  const fileName = attrs.name || json.name || json.fileName || '';
  const mimeType = attrs.mime_type || attrs.mimeType || json.mimeType || '';
  const extension = attrs.extn || (fileName.includes('.') ? fileName.split('.').pop() : '') || '';
  return {
    json: {
      source: 'workdrive',
      sourceFolderId,
      processedFolderId,
      fileId,
      fileName,
      mimeType,
      extension,
    },
  };
}).filter(({ json }) => {
  if (!json.fileId || !json.fileName) return false;
  const lowerName = json.fileName.toLowerCase();
  const lowerMime = String(json.mimeType || '').toLowerCase();
  const lowerExt = String(json.extension || '').toLowerCase();
  return lowerName.endsWith('.pdf') || lowerMime.includes('pdf') || lowerExt === 'pdf';
});

return $input.all().map(({ json }) => ({
  json: {
    ...json,
    source: String(json.source || '').trim().toLowerCase(),
    workdrive_file_id: String(json.workdrive_file_id || json.workdriveFileId || '').trim(),
    processed_folder_id: String(json.processed_folder_id || json.processedFolderId || '').trim(),
  },
})).filter(({ json }) => Boolean(json.workdrive_file_id && json.processed_folder_id));

const d = $input.item.json;
const logData = {
  resume_id: d.resume_hash || d.resumeHash || 'unknown',
  candidate_id: d.id || d.email || 'unknown',
  workflow_version: 'enterprise-v1.0',
  ai_model_extraction: 'google-vertex-gemini',
  ai_model_scoring: 'openrouter+ollama',
  prompt_version: 'scoring-v3-7cat',
  processing_ms: d.processing_ms || 0,
  submitted_at: d.submitted_at || new Date().toISOString(),
  status: 'COMPLETED'
};
return { json: logData };
